function irA(id){document.getElementById(id).scrollIntoView({behavior:"smooth"});}
function mostrarObra(i){const b=document.getElementById("worksInfo");b.innerHTML="<strong>"+obras[i].t+"</strong><br>"+obras[i].x;b.classList.add("show");b.scrollIntoView({behavior:"smooth",block:"nearest"});}
function toast(msg){const t=document.getElementById("toast");t.textContent=msg;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2200);}


function hablarLia(texto){
  const bubble=document.getElementById("guideBubble");
  const avatar=document.getElementById("guideAvatar");
  if(bubble){ bubble.innerHTML="<strong>Lía 💗</strong><br>"+texto; }
  if(avatar){ avatar.classList.remove("guide-pulse"); void avatar.offsetWidth; avatar.classList.add("guide-pulse"); }
  if("speechSynthesis" in window){
    speechSynthesis.cancel();
    const u=new SpeechSynthesisUtterance(texto); u.lang="es-MX"; u.rate=.90; u.pitch=1.25;
    const voces=speechSynthesis.getVoices();
    const preferida=voces.find(v=>/^es(-MX|-ES|-US)?/i.test(v.lang) && /female|mujer|woman|paulina|monica|helena|sabina|elena/i.test(v.name));
    if(preferida) u.voice=preferida;
    speechSynthesis.speak(u);
  }
}
const instruccionesLia={
 collage:"¡Vamos al collage! Elige una imagen de las opciones o sube las tuyas. Después arrástralas al lienzo, muévelas hasta que te guste la composición y elige un marco. Si te equivocas, selecciona una imagen y pulsa Suprimir.",
 pintura:"Ahora toca pintar. Elige un color y el grosor del pincel. Puedes usar una plantilla, dibujar libremente, borrar y volver a empezar. No busques que quede perfecto: ¡quiero ver tus ideas!",
 poema:"¡Llegamos al poema! Escoge un tema, usa las palabras que te inspiran y escribe tu propio texto. Si quieres, agrega tu dibujo y graba tu voz para convertirlo en una pequeña obra sonora."
};
function guiaActividad(tab){
  const pose=tab==="collage"?"collage":tab==="pintura"?"pintura":"poema";
  setLiaPose(pose);
  if(instruccionesLia[tab]) hablarSuave(instruccionesLia[tab]);
}

let lastActivity="collage";
function abrirActividad(tab){
 lastActivity=tab;
 document.getElementById("estudio").style.display="block";
 document.querySelectorAll(".studio-view").forEach(v=>v.classList.remove("active"));
 document.getElementById("view-"+tab).classList.add("active");
 document.querySelectorAll(".tab").forEach(b=>b.classList.toggle("active",b.dataset.tab===tab));
 document.getElementById("studioTitle").textContent=tab==="collage"?"Collage interactivo":tab==="pintura"?"Pintura":"Poema + canción";
 document.getElementById("estudio").scrollIntoView({behavior:"smooth",block:"start"});
 setTimeout(()=>guiaActividad(tab),450);
}
function volverMenu(){document.getElementById("actividades").scrollIntoView({behavior:"smooth"});}

const svgData=(bg,shape,label)=>{
 const s=`<svg xmlns="http://www.w3.org/2000/svg" width="500" height="400"><rect width="500" height="400" fill="${bg}"/><circle cx="120" cy="120" r="75" fill="rgba(255,255,255,.45)"/><path d="${shape}" fill="rgba(255,255,255,.82)"/><text x="250" y="340" text-anchor="middle" font-family="Georgia" font-size="38" fill="#352d32">${label}</text></svg>`;
 return "data:image/svg+xml;charset=UTF-8,"+encodeURIComponent(s);
};
