const categoryGrid=document.getElementById("categoryGrid");
categorias.forEach((c,i)=>{
 const d=document.createElement("div");d.className="category-img";d.draggable=true;d.dataset.src=svgData(c[1],c[2],c[3]);d.innerHTML=`<img src="${d.dataset.src}"><span>${c[3]}</span>`;
 d.onclick=()=>addCollageImage(d.dataset.src);d.addEventListener("dragstart",e=>e.dataTransfer.setData("text/plain",d.dataset.src));categoryGrid.appendChild(d);
});

const stage=document.getElementById("collageStage");let selectedCollage=null;
stage.addEventListener("dragover",e=>{e.preventDefault();stage.classList.add("drag-over")});
stage.addEventListener("dragleave",()=>stage.classList.remove("drag-over"));
stage.addEventListener("drop",e=>{e.preventDefault();stage.classList.remove("drag-over");const src=e.dataTransfer.getData("text/plain");if(src)addCollageImage(src,e.offsetX,e.offsetY);});
function addCollageImage(src,x,y){
 const img=document.createElement("img");img.src=src;img.className="collage-item";img.draggable=false;
 const rect=stage.getBoundingClientRect();img.style.left=Math.max(8,(x??stage.clientWidth/2)-65)+"px";img.style.top=Math.max(8,(y??stage.clientHeight/2)-65)+"px";
 img.onclick=e=>{e.stopPropagation();selectCollage(img)};makeMovable(img);stage.appendChild(img);document.getElementById("collageHint").style.display="none";selectCollage(img);
}
function selectCollage(el){document.querySelectorAll(".collage-item").forEach(x=>x.classList.remove("selected"));selectedCollage=el;el.classList.add("selected");stage.focus();}
function makeMovable(el){
 let moving=false,ox=0,oy=0;
 el.addEventListener("pointerdown",e=>{moving=true;selectCollage(el);el.setPointerCapture(e.pointerId);ox=e.clientX-el.offsetLeft;oy=e.clientY-el.offsetTop;el.style.cursor="grabbing"});
 el.addEventListener("pointermove",e=>{if(!moving)return;const r=stage.getBoundingClientRect();el.style.left=Math.max(0,Math.min(stage.clientWidth-el.offsetWidth,e.clientX-r.left-ox))+"px";el.style.top=Math.max(0,Math.min(stage.clientHeight-el.offsetHeight,e.clientY-r.top-oy))+"px"});
 el.addEventListener("pointerup",()=>{moving=false;el.style.cursor="grab"});
}
stage.addEventListener("click",()=>{if(selectedCollage)selectedCollage.classList.remove("selected");selectedCollage=null});
document.addEventListener("keydown",e=>{if((e.key==="Delete"||e.key==="Backspace")&&selectedCollage){selectedCollage.remove();selectedCollage=null;if(!stage.querySelector(".collage-item"))document.getElementById("collageHint").style.display="grid"}});
function cargarImagenes(e){[...e.target.files].forEach(file=>{const r=new FileReader();r.onload=()=>addCollageImage(r.result);r.readAsDataURL(file)});e.target.value="";}
function limpiarCollage(){stage.querySelectorAll(".collage-item").forEach(x=>x.remove());document.getElementById("collageHint").style.display="grid";}
function setFrame(f){stage.className="collage-stage frame-"+f;document.querySelectorAll(".frame-choice").forEach(b=>b.classList.toggle("active",b.dataset.frame===f));}

const canvas=document.getElementById("paintCanvas"),ctx=canvas.getContext("2d");ctx.fillStyle="#fff";ctx.fillRect(0,0,canvas.width,canvas.height);
let drawing=false,eraser=false,lastX=0,lastY=0;
function pos(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height}}
function paintStart(e){drawing=true;const p=pos(e);lastX=p.x;lastY=p.y;canvas.setPointerCapture(e.pointerId)}
function paintMove(e){if(!drawing)return;const p=pos(e);ctx.lineWidth=+document.getElementById("paintSize").value;ctx.lineCap="round";ctx.lineJoin="round";ctx.strokeStyle=eraser?"#fff":document.getElementById("paintColor").value;ctx.beginPath();ctx.moveTo(lastX,lastY);ctx.lineTo(p.x,p.y);ctx.stroke();lastX=p.x;lastY=p.y}
canvas.addEventListener("pointerdown",paintStart);canvas.addEventListener("pointermove",paintMove);canvas.addEventListener("pointerup",()=>drawing=false);canvas.addEventListener("pointerleave",()=>drawing=false);
document.getElementById("paintSize").oninput=e=>document.getElementById("sizeValue").textContent=e.target.value;
function setEraser(v){eraser=v;toast(v?"Borrador activado":"Pincel activado")}
function clearPaint(){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle="#fff";ctx.fillRect(0,0,canvas.width,canvas.height);}
