let mediaRecorder=null,audioChunks=[],audioURL="";
async function toggleRecording(){
 if(mediaRecorder&&mediaRecorder.state==="recording"){mediaRecorder.stop();return}
 try{
  const stream=await navigator.mediaDevices.getUserMedia({audio:true});audioChunks=[];
  mediaRecorder=new MediaRecorder(stream);
  mediaRecorder.ondataavailable=e=>{if(e.data.size)audioChunks.push(e.data)};
  mediaRecorder.onstop=()=>{
    stream.getTracks().forEach(t=>t.stop());
    const blob=new Blob(audioChunks,{type:"audio/webm"});
    audioURL=URL.createObjectURL(blob);
    document.getElementById("audioPlayer").src=audioURL;
    document.getElementById("recordingStatus").textContent="✓ Grabación lista para escuchar y guardar.";
    document.getElementById("recordBtn").textContent="🔴 Grabar de nuevo";
    const reader=new FileReader();
    reader.onload=()=>{appData.audio={dataUrl:reader.result,date:new Date().toLocaleString("es-MX")};try{saveAppData()}catch(e){toast("La grabación es demasiado grande para guardarse localmente.")}};
    reader.readAsDataURL(blob);
  };
  mediaRecorder.start();document.getElementById("recordingStatus").textContent="● Grabando… vuelve a pulsar para terminar.";document.getElementById("recordBtn").textContent="⏹ Terminar grabación";
 }catch(err){document.getElementById("recordingStatus").textContent="No se pudo acceder al micrófono. Revisa los permisos del navegador."}
}
function reproducirAudio(){const a=document.getElementById("audioPlayer");if(a.src)a.play();else toast("Primero graba tu poema.");}
function detenerAudio(){document.getElementById("audioPlayer").pause();}

function guardarProyecto(){
 const data={collage:[...stage.querySelectorAll(".collage-item")].map(i=>({src:i.src,left:i.style.left,top:i.style.top})),frame:stage.className,poem:document.getElementById("poemText").value,theme:document.getElementById("poemTheme").value,paint:canvas.toDataURL("image/png")};
 localStorage.setItem("galeria2030Proyecto",JSON.stringify(data));appData.projects.push(snapshotProject(lastActivity));saveAppData();toast("✓ Proyecto guardado.");
 document.getElementById("collageStatus").textContent="✓ Guardado. Puedes volver y continuar más tarde.";
}
function guardarPoema(){actualizarPoema();const text=document.getElementById("poemText").value.trim();if(!text){toast("Escribe primero tu poema.");return}localStorage.setItem("galeria2030Poema",JSON.stringify({theme:document.getElementById("poemTheme").value,text,frame:document.getElementById("poemPreview").className,withDrawing:document.getElementById("attachDrawing").checked}));appData.projects.push(snapshotProject("poema"));saveAppData();document.getElementById("poemStatus").textContent="✓ Poema guardado.";toast("✓ Poema guardado.");}

