/* Persistencia mejorada */
const STORAGE_KEY="galeria2030DataV2";
let appData=JSON.parse(localStorage.getItem(STORAGE_KEY)||'{"projects":[],"conversation":[],"audio":null}');
function saveAppData(){localStorage.setItem(STORAGE_KEY,JSON.stringify(appData));renderProgress();}
function snapshotProject(kind){
  actualizarPoema();
  return {
    id:Date.now(),kind,
    date:new Date().toLocaleString("es-MX"),
    collage:[...stage.querySelectorAll(".collage-item")].map(i=>({src:i.src,left:i.style.left,top:i.style.top})),
    frame:stage.className,
    paint:canvas.toDataURL("image/png"),
    theme:document.getElementById("poemTheme").value,
    poem:document.getElementById("poemText").value,
    withDrawing:document.getElementById("attachDrawing").checked,
    audio:appData.audio||null
  };
}
function saveConversationAnswer(question,answer){
  appData.conversation.push({question,answer,date:new Date().toLocaleString("es-MX")});
  saveAppData();
}
function renderProgress(){
  const sum=document.getElementById("progressSummary"), wall=document.getElementById("publicCreations");
  if(!sum||!wall)return;
  const projects=appData.projects||[], conv=appData.conversation||[];
  sum.innerHTML=[
    ["🎨",projects.filter(x=>x.kind==="pintura").length,"Pinturas"],
    ["✂️",projects.filter(x=>x.kind==="collage").length,"Collages"],
    ["📝",projects.filter(x=>x.kind==="poema").length,"Poemas"],
    ["💬",conv.length,"Respuestas"],
    ["🎙️",appData.audio?1:0,"Grabación"]
  ].map(x=>`<article class="card"><div class="symbol">${x[0]}</div><h3>${x[1]}</h3><p>${x[2]} guardados</p></article>`).join("");

  const cards=projects.slice().reverse().map(p=>{
    const a=(p.audio&&p.audio.dataUrl)?p.audio:null;
    const audio=a?`<div style="margin-top:10px"><strong>🎙️ Voz:</strong><audio controls src="${a.dataUrl}" style="width:100%;margin-top:6px"></audio></div>`:"";
    const extra=p.kind==="poema" ? `<p><strong>${p.theme||"Poema"}</strong></p><p>${(p.poem||"").replace(/</g,"&lt;").replace(/\n/g,"<br>")}</p>${audio}` :
      p.kind==="pintura" ? `<img src="${p.paint}" alt="Pintura guardada" style="width:100%;border-radius:12px">` :
      `<p>${(p.collage||[]).length} imagen(es) en el collage.</p>`;
    return `<article class="card"><span class="tag">${p.kind}</span><p class="small">${p.date}</p>${extra}</article>`;
  });
  if(appData.audio?.dataUrl && !projects.some(p=>p.audio?.dataUrl)){
    cards.unshift(`<article class="card"><span class="tag">voz</span><p class="small">${appData.audio.date||""}</p><h3>🎙️ Grabación guardada</h3><audio controls src="${appData.audio.dataUrl}" style="width:100%"></audio></article>`);
  }
  wall.innerHTML=cards.join("") || '<article class="card"><h3>Aún no hay creaciones</h3><p>Guarda tu primera actividad y aparecerá aquí.</p></article>';
}
function guardarProyectoMejorado(kind){
  const p=snapshotProject(kind||lastActivity);
  appData.projects.push(p);
  saveAppData();
  toast("✓ Progreso guardado.");
}
function elegirVozSuave(){
  if(!("speechSynthesis" in window))return null;
  const voces=speechSynthesis.getVoices();
  return voces.find(v=>/^es-MX/i.test(v.lang)&&/female|mujer|woman|Paulina|Monica|Google español/i.test(v.name))
      || voces.find(v=>/^es/i.test(v.lang)&&/female|mujer|woman|Paulina|Monica|Google español/i.test(v.name))
      || voces.find(v=>/^es-MX/i.test(v.lang))
      || voces.find(v=>/^es/i.test(v.lang))
      || null;
}
function hablarSuave(texto, avatarId="guideAvatar"){
  if(!("speechSynthesis" in window))return;
  speechSynthesis.cancel();
  const avatar=document.getElementById(avatarId);
  const guide=document.getElementById("guideCharacter");
  if(guide)guide.classList.add("talk");
  if(avatar){avatar.classList.remove("guide-pulse");void avatar.offsetWidth;avatar.classList.add("guide-pulse");}
  const u=new SpeechSynthesisUtterance(texto);u.lang="es-MX";u.rate=.86;u.pitch=1.48;u.volume=.95;
  const voice=elegirVozSuave();if(voice)u.voice=voice;
  u.onend=()=>{if(guide)guide.classList.remove("talk")};
  speechSynthesis.speak(u);
}
function cargarProyectoGuardado(){
  const p=appData.projects[appData.projects.length-1];
  if(!p)return;
  if(p.paint){const im=new Image();im.onload=()=>ctx.drawImage(im,0,0);im.src=p.paint;}
  if(p.poem){document.getElementById("poemText").value=p.poem;document.getElementById("poemTheme").value=p.theme||"Igualdad";actualizarTema();}
}
window.addEventListener("beforeunload",()=>{try{saveAppData()}catch(e){}});

