let guiaIndex = 0;


function ocultarGuia(e){
  if(e)e.stopPropagation();
  if("speechSynthesis" in window) speechSynthesis.cancel();
  document.body.classList.add("guide-hidden");
  const btn=document.getElementById("showGuideBtn");
  if(btn)btn.style.display="block";
}
function mostrarGuia(){
  document.body.classList.remove("guide-hidden");
  const btn=document.getElementById("showGuideBtn");
  if(btn)btn.style.display="none";
}

function guiaMostrar(index, hablar=true){
  guiaIndex = (index + guiaPasos.length) % guiaPasos.length;
  const paso = guiaPasos[guiaIndex];
  const bubble = document.getElementById("guideBubble");
  bubble.innerHTML = "<strong>Lía 💬</strong><br>" + paso.texto;
  setLiaPose(paso.pose || "welcome");
  if(hablar) hablarSuave(paso.texto);
}
function guiaSiguiente(e){ if(e)e.stopPropagation(); guiaMostrar(guiaIndex+1,true); }
function guiaAnterior(e){ if(e)e.stopPropagation(); guiaMostrar(guiaIndex-1,true); }
function guiaHabla(e){ if(e)e.stopPropagation(); guiaMostrar(guiaIndex,true); }

document.getElementById("guideCharacter").addEventListener("click", function(e){
  if(e.target.closest("button")) return;
  guiaSiguiente(e);
});

// Intentar acompañar la navegación existente.
const guiaOriginalIrA = window.irA;
window.irA = function(seccion){
  if(typeof guiaOriginalIrA === "function") guiaOriginalIrA(seccion);
  const mapa = {inicio:0, agenda:1, galeria:4, actividades:5, reto:5, evaluacion:9, studio:5};
  if(mapa[seccion] !== undefined) guiaMostrar(mapa[seccion], false);
};

// Si la versión del estudio usa botones/tabs sin pasar por irA, observar cambios de sección visibles.
document.addEventListener("DOMContentLoaded", ()=>{
  setTimeout(()=>guiaMostrar(0,true),600);
});


// Conversación final con Lía
const conversacion = [
  {
    etapa:"Inicio",
    pregunta:"¿Te gustó la experiencia de crear mientras aprendías sobre la Agenda 2030?",
    opciones:["😍 ¡Sí! Me gustó mucho.","🙂 Me gustó, aunque cambiaría algunas cosas.","🤔 No fue lo que esperaba."]
  },
  {
    etapa:"Inicio",
    pregunta:"¿Qué actividad disfrutaste más: collage, pintura, poema o explorar la galería?",
    opciones:["✂️ Collage","🖌️ Pintura","✍️ Poema","🖼️ Explorar la galería"]
  },
  {
    etapa:"Desarrollo",
    pregunta:"Ahora quiero saber algo importante: ¿estás de acuerdo con nuestro objetivo de aprender creando y usar el arte para reflexionar sobre igualdad e inclusión?",
    opciones:["⚖️ Sí, estoy de acuerdo.","💭 Estoy de acuerdo con algunas partes.","❓ Todavía tengo dudas."]
  },
  {
    etapa:"Desarrollo",
    pregunta:"¿Crees que hablar de igualdad de género es importante para todas las personas y no solamente para las niñas?",
    opciones:["🌎 Sí, nos involucra a todas las personas.","🤝 Sí, porque podemos aprender unos de otros.","💬 Quiero explicarte mi opinión."]
  },
  {
    etapa:"Final",
    pregunta:"Si pudieras cambiar algo de tu escuela, comunidad o entorno para hacerlo más justo e inclusivo, ¿qué cambiarías?",
    libre:true
  },
  {
    etapa:"Final",
    pregunta:"Última pregunta: ¿qué mensaje te gustaría dejarle a otra persona que visite la Galería 2030?",
    libre:true
  }
];
let convIndex=0;
let convUltimaRespuesta="";

function convRender(){
  const paso=conversacion[convIndex];
  document.getElementById("convStage").textContent=paso.etapa;
  document.getElementById("convCounter").textContent=(convIndex+1)+" / "+conversacion.length;
  document.getElementById("convQuestion").textContent=paso.pregunta;
  document.getElementById("convResult").style.display="none";
  document.getElementById("convNext").style.display="none";
  document.getElementById("convInputArea").style.display=paso.libre?"block":"none";
  const opts=document.getElementById("convOptions");
  opts.innerHTML="";
  if(paso.libre){
    document.getElementById("convInput").value="";
    opts.style.display="none";
  }else{
    opts.style.display="flex";
    paso.opciones.forEach(op=>{
      const b=document.createElement("button");
      b.textContent=op;
      b.onclick=()=>responderConversacion(op);
      opts.appendChild(b);
    });
  }
  const avatar=document.getElementById("finalGuideAvatar");
  avatar.classList.remove("guide-pulse"); void avatar.offsetWidth; avatar.classList.add("guide-pulse");
  convHablar("Lía dice: "+paso.pregunta);
}
function responderConversacion(respuesta){
  convUltimaRespuesta=respuesta;
  saveConversationAnswer(conversacion[convIndex].pregunta,respuesta);
  const respuestas = [
    "¡Gracias por decírmelo! Lo importante es que pudiste participar y formar tu propia opinión.",
    "¡Qué interesante elección! Cada forma de crear nos permite mirar el tema desde una perspectiva diferente.",
    "Me alegra conocer tu postura. La Agenda 2030 también nos invita a pensar y dialogar, no solo a memorizar objetivos.",
    "Exactamente. La igualdad es una responsabilidad compartida y todas las personas podemos aportar.",
  ];
  let mensaje=respuestas[Math.min(convIndex,3)];
  document.getElementById("convBubble").innerHTML="<strong>Lía 💬</strong><br>"+mensaje;
  document.getElementById("convResult").textContent="Tu respuesta: "+respuesta;
  document.getElementById("convResult").style.display="block";
  document.getElementById("convNext").style.display="inline-block";
  convHablar(mensaje);
}
function enviarRespuestaLibre(){
  const input=document.getElementById("convInput");
  const texto=input.value.trim();
  if(!texto){input.focus();return;}
  convUltimaRespuesta=texto;
  saveConversationAnswer(conversacion[convIndex].pregunta,texto);
  let mensaje = convIndex===4
    ? "Me encanta que lo hayas pensado desde tu propio entorno. Una transformación empieza cuando identificamos qué queremos mejorar."
    : "Gracias por compartir ese mensaje. Tu voz también forma parte de esta experiencia y puede inspirar a otras personas.";
  document.getElementById("convBubble").innerHTML="<strong>Lía 💬</strong><br>"+mensaje;
  document.getElementById("convResult").textContent="Tu respuesta: "+texto;
  document.getElementById("convResult").style.display="block";
  document.getElementById("convNext").style.display="inline-block";
  convHablar(mensaje);
}
function convSiguiente(){
  if(convIndex<conversacion.length-1){
    convIndex++;
    convRender();
  }else{
    document.getElementById("convQuestion").textContent="¡Conversación terminada!";
    document.getElementById("convOptions").innerHTML="";
    document.getElementById("convOptions").style.display="none";
    document.getElementById("convInputArea").style.display="none";
    document.getElementById("convNext").style.display="none";
    document.getElementById("convStage").textContent="Despedida";
    document.getElementById("convBubble").innerHTML="<strong>Lía 💛</strong><br>Gracias por participar. Recuerda: no necesitas ser artista ni especialista para tener una idea, cuestionarla y convertirla en una acción. ¡Nos vemos en la próxima creación!";
    convHablar("Gracias por participar. Recuerda: no necesitas ser artista ni especialista para tener una idea, cuestionarla y convertirla en una acción. ¡Nos vemos en la próxima creación!");
  }
}
function convRepetir(){
  const bubble=document.getElementById("convBubble").innerText;
  convHablar(bubble);
}
function convHablar(texto){hablarSuave(texto,"finalGuideAvatar");}
document.addEventListener("DOMContentLoaded",()=>{setTimeout(convRender,500);setTimeout(renderProgress,200);});
